                        c += 1;
                    }
                    if ((nchunks < occn) && ((nchunks * 2) <= occn)) {
                        ok = 1;
                        s = 0;
                        while (s < nchunks) {
                            int si = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                            int a = TbChunkA(wd, et, wl, sg, ch, si);
                            int b = TbChunkB(wd, wl, sg, ch, si);
                            if (a != b) {
                                ok = 0;
                            }
                            if (emon.Port.CellsAt(occ, a) != 1) {
                                ok = 0;
                            }
                            s += 1;
                        }
                        cont = ok;
                    }
                }
            }
            if (cont == 0) {
                rows += 1;
                c = 0;
                while (c < ncols) {
                    emon.Port.CellsSet(occ, c, 0);
                    c += 1;
                }
            }
            s = 0;
            while (s < emon.Port.CellsAt(rw, (r * Rws) + 9)) {
                int si = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                int a = TbChunkA(wd, et, wl, sg, ch, si);
                int b = TbChunkB(wd, wl, sg, ch, si);
                c = a;
                while (c <= b) {
                    emon.Port.CellsSet(occ, c, 1);
                    c += 1;
                }
                s += 1;
            }
            emon.Port.CellsPush(rmap, rows);
            r += 1;
        }
        return rows + 1;
    }
    internal static int TbCut(emon.Port.Cells ch, int k, int lo, int hi) {
        // The boundary before column k: lo for the first, else the midpoint of channel k-1; hi after the last.
        int n = emon.Port.CellsLen(ch) / 2;
        if (k <= 0) {
            return lo;
        }
        if (k > n) {
            return hi;
        }
        return (emon.Port.CellsAt(ch, (k - 1) * 2) + emon.Port.CellsAt(ch, ((k - 1) * 2) + 1)) / 2;
    }
    internal static int TbCutList(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells rm, int ra, int rb, int minx, int maxx, emon.Port.Cells cl) {
        // D559: the x of every vertical rule of `rm` that is a column cut of the rows ra..rb, in `cl` (emptied first). A rule is one when it
        // lies inside the rows' extent minx..maxx, runs along three in five of the rows at least (two or more) and passes through no word of those
        // rows (a rule through a word is a strike or a frame, not the border between two cells). Answers how many.
        int nrl = TbRowsOf(rm, Rls);
        int n = rb - ra;
        int i = 0;
        int r = 0;
        int k = 0;
        int p = 0;
        int spanned = 0;
        int crossed = 0;
        int cy = 0;
        int w = 0;
        emon.Port.CellsDrop(cl, 0);
        if (n < 2) {
            return 0;
        }
        while (i < nrl) {
            if (emon.Port.CellsAt(rm, i * Rls) == 1) {
                p = emon.Port.CellsAt(rm, (i * Rls) + 1);
                if ((p > minx) && (p < maxx)) {
                    spanned = 0;
                    crossed = 0;
                    r = ra;
                    while (r < rb) {
                        cy = (emon.Port.CellsAt(rw, (r * Rws) + 6) + emon.Port.CellsAt(rw, (r * Rws) + 7)) / 2;
                        if ((cy >= emon.Port.CellsAt(rm, (i * Rls) + 2)) && (cy <= emon.Port.CellsAt(rm, (i * Rls) + 3))) {
                            spanned += 1;
                            k = 0;
                            while (k < emon.Port.CellsAt(rw, (r * Rws) + 1)) {
                                w = emon.Port.CellsAt(wl, emon.Port.CellsAt(rw, r * Rws) + k);
                                if ((Evidence.WdGet(wd, w, Evidence.HdX0()) < p) && (Evidence.WdGet(wd, w, Evidence.HdX1()) > p)) {
                                    crossed = 1;
                                }
                                k += 1;
                            }
                        }
                        r += 1;
                    }
                    if ((crossed == 0) && ((spanned >= 2) && ((spanned * 5) >= (n * 3)))) {
                        emon.Port.CellsPush(cl, p);
                        emon.Port.CellsPush(cl, emon.Port.CellsAt(rm, (i * Rls) + 2));
                        emon.Port.CellsPush(cl, emon.Port.CellsAt(rm, (i * Rls) + 3));
                    }
                }
            }
            i += 1;
        }
        return emon.Port.CellsLen(cl);
    }
    internal static int TbChannelAdd(emon.Port.Cells ch, int p) {
        // D559: a channel of no width at x p, in its place among the channels `ch` (pairs of start and end, in order of x), so that a column
        // boundary stands at p: nothing is added when p lies in a channel already (its midpoint is the boundary, with words either side).
        // Answers 1 when one was added.
        int n = emon.Port.CellsLen(ch) / 2;
        int i = 0;
        int at = 0;
        int k = 0;
        while (i < n) {
            if ((emon.Port.CellsAt(ch, i * 2) <= p) && (p <= emon.Port.CellsAt(ch, (i * 2) + 1))) {
                return 0;
            }
            if (emon.Port.CellsAt(ch, i * 2) < p) {
                at += 1;
            }
            i += 1;
        }
        emon.Port.CellsPush(ch, 0);
        emon.Port.CellsPush(ch, 0);
        k = emon.Port.CellsLen(ch) - 1;
        while (k >= ((at * 2) + 2)) {
            emon.Port.CellsSet(ch, k, emon.Port.CellsAt(ch, k - 2));
            k -= 1;
        }
        emon.Port.CellsSet(ch, at * 2, p);
        emon.Port.CellsSet(ch, (at * 2) + 1, p);
        return 1;
    }
    internal static int TbSubEnd(emon.Port.Cells wd, emon.Port.Cells wl, emon.Port.Cells cl, int k, int kend, int cy) {
        // D559: where the words k..kend of one chunk (indices into `wl`), on a row whose centre is at y `cy`, are cut by a column cut of `cl`
        // (x, from, to: D563, a cut cuts the rows it runs along and no other, or a phrase in a row beside a check box's border is cut in two): the
        // end (exclusive) of the stretch that begins at the word k and has no cut between its words (`kend` when there is none).
        int e = k + 1;
        int j = 0;
        int split = 0;
        while ((e < kend) && (split == 0)) {
            j = 0;
            while (j < emon.Port.CellsLen(cl)) {
                if ((Evidence.WdGet(wd, emon.Port.CellsAt(wl, e - 1), Evidence.HdX1()) <= emon.Port.CellsAt(cl, j)) && ((emon.Port.CellsAt(cl, j) <= Evidence.WdGet(wd, emon.Port.CellsAt(wl, e), Evidence.HdX0())) && ((cy >= emon.Port.CellsAt(cl, j + 1)) && (cy <= emon.Port.CellsAt(cl, j + 2))))) {
                    split = 1;
                }
                j += 3;
            }
            if (split == 0) {
                e += 1;
            }
        }
        return e;
    }
    internal static bool TbCrossed(emon.Port.Cells wd, int w0, int w1, int x, int ya, int yb) {
        // P12.2: does a word whose centre is in the rows ya..yb lie across x (starts before it, ends after it).
        int w = w0;
        while (w < w1) {
            if ((Evidence.WdGet(wd, w, Evidence.HdX0()) < x) && (Evidence.WdGet(wd, w, Evidence.HdX1()) > x)) {
                if ((Evidence.WdGet(wd, w, Evidence.HdTlen()) > 0) && TbUpright(wd, w)) {
                    int cy = (Evidence.WdGet(wd, w, Evidence.HdY0()) + Evidence.WdGet(wd, w, Evidence.HdY1())) / 2;
                    if ((cy >= ya) && (cy <= yb)) {
                        return 1 == 1;
                    }
                }
            }
            w += 1;
        }
        return 0 == 1;
    }
    internal static int TbSplitRows(emon.Port.Cells rm, int root, emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, emon.Port.Cells xs, emon.Port.Cells ys, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells occ, emon.Port.Cells rmap, emon.Port.Cells so, emon.Port.Cells bd) {
