        int from = emon.Port.CellsAt(tc, cb + 8);
        int k = 0;
        if (n == 0) {
            return -1;
        }
        while (k < n) {
            if ((Evidence.WdGet(wd, emon.Port.CellsAt(tw, from + k), Evidence.WfStyle()) & Model.SyBold()) == 0) {
                return 0;
            }
