    internal static int TbRowStat(emon.Port.Cells tc, int cfirst, int cend, int r, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw, int what) {
        // Of the cells that start in row r: what 0 how many are not empty, 1 how many are bold, 2 how many are
        // numeric, 3 how many there are.
        int c = cfirst;
        int n = 0;
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) == r) {
                if (what == 3) {
                    n += 1;
                }
                if ((what == 0) && (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0)) {
                    n += 1;
                }
                if ((what == 1) && (TbCellBold(wd, tw, tc, c) == 1)) {
                    n += 1;
                }
                if ((what == 2) && (TbCellNumeric(wd, et, tw, tc, c) == 1)) {
                    n += 1;
                }
            }
            c += 1;
        }
        return n;
    }
    internal static bool TbRowBold(emon.Port.Cells tc, int cfirst, int cend, int r, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tw) {
        // Is row r bold: it has cells and every one that is not empty is bold.
        int ne = TbRowStat(tc, cfirst, cend, r, wd, et, tw, 0);
        return (ne > 0) && (TbRowStat(tc, cfirst, cend, r, wd, et, tw, 1) == ne);
