                if (emon.Port.CellsAt(tc, (c * Tcs) + 1) < mincol) {
                    mincol = emon.Port.CellsAt(tc, (c * Tcs) + 1);
                }
                if (emon.Port.CellsAt(tc, c * Tcs) == r) {
                    cnt += 1;
                    only = c;
                }
