        int r = 0;
        int j = 0;
        int same = 1;
        if (tl < 1) {
            return 0 == 1;
        }
        if (emon.Port.CellsAt(et, ts + (tl - 1)) == 46) {
            tl -= 1;
        }
        while (r < 9) {
            if (TbKw[r * 9 + 0] == tl) {
                same = 1;
                j = 0;
                while (j < tl) {
                    if (TbLower(emon.Port.CellsAt(et, ts + j)) != TbKw[r * 9 + (j + 1)]) {
                        same = 0;
                    }
                    j += 1;
                }
                if (same == 1) {
                    return 1 == 1;
                }
            }
            r += 1;
        }
        return 0 == 1;
    }
    internal static bool TbIsLabelNumber(emon.Port.Cells wd, emon.Port.Cells et, int w) {
        // A table number: starts with a digit, or a capital letter and a digit (S1).
        int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
        if (tl < 1) {
            return 0 == 1;
        }
        int c0 = emon.Port.CellsAt(et, ts);
        if ((c0 >= 48) && (c0 <= 57)) {
            return 1 == 1;
        }
        if ((tl >= 2) && ((c0 >= 65) && (c0 <= 90))) {
            int c1 = emon.Port.CellsAt(et, ts + 1);
            return (c1 >= 48) && (c1 <= 57);
        }
        return 0 == 1;
    }
    internal static bool TbLineLabel(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, int l) {
        // Does line l start with a table keyword and a table number.
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        if (Evidence.LnGet(ln, l, Evidence.LhCount()) < 2) {
            return 0 == 1;
        }
        return TbIsLabelWord(wd, et, w0) && TbIsLabelNumber(wd, et, w0 + 1);
    }
    internal static int TbCaption(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, int l0, int l1, emon.Port.Cells tq) {
        // Find the caption of table k among the unclaimed lines l0..l1: a line that starts with a table keyword
        // and a number, over the table or under it within two and a half line heights, preferring the one over it;
        // the lines on its baseline to its right and the lines under it that continue it are part of it. They are
        // claimed and their numbers pushed on `tq` (qfirst, qcount in the table's cells 14 and 15).
        int b = k * Tbs;
        int tx0 = emon.Port.CellsAt(tb, b + 1);
        int ty0 = emon.Port.CellsAt(tb, b + 2);
        int tx1 = emon.Port.CellsAt(tb, b + 3);
        int ty1 = emon.Port.CellsAt(tb, b + 4);
        int l = l0;
        int best = -1;
        int bestd = 2000000000;
        int above = 0;
        while (l < l1) {
            if (Evidence.LnGet(ln, l, 15) == 0) {
                if (TbLineLabel(wd, et, ln, l)) {
                    if ((Evidence.LnGet(ln, l, Evidence.LhX0()) < tx1) && (Evidence.LnGet(ln, l, Evidence.LhX1()) > tx0)) {
                        int lht = Evidence.LnGet(ln, l, Evidence.LhY1()) - Evidence.LnGet(ln, l, Evidence.LhY0());
                        int da = ty0 - Evidence.LnGet(ln, l, Evidence.LhY1());
                        int db = Evidence.LnGet(ln, l, Evidence.LhY0()) - ty1;
                        if ((da >= -300) && ((da * 2) <= (lht * 5))) {
                            if (TbAbs(da) < bestd) {
                                best = l;
                                bestd = TbAbs(da);
                                above = 1;
                            }
                        }
                        if ((db >= -300) && (((db * 2) <= (lht * 5)) && (above == 0))) {
                            if (TbAbs(db) < bestd) {
                                best = l;
                                bestd = TbAbs(db);
                            }
                        }
                    }
                }
            }
            l += 1;
        }
        if (best < 0) {
            return 0;
        }
        emon.Port.CellsSet(tb, b + 14, emon.Port.CellsLen(tq));
        emon.Port.CellsPush(tq, best);
        Evidence.LnSet(ln, best, 15, TbHeld + k);
        int h = Evidence.LnGet(ln, best, Evidence.LhY1()) - Evidence.LnGet(ln, best, Evidence.LhY0());
        int curx1 = Evidence.LnGet(ln, best, Evidence.LhX1());
        int cury1 = Evidence.LnGet(ln, best, Evidence.LhY1());
        int more = 1;
        int rounds = 0;
        int pick = -1;
        l = l0;
        while (l < l1) {
            if (Evidence.LnGet(ln, l, 15) == 0) {
                if ((Evidence.LnGet(ln, l, Evidence.LhX0()) > (curx1 - 100)) && ((Evidence.LnGet(ln, l, Evidence.LhX0()) - curx1) <= (2 * h))) {
                    if (TbAbs(Evidence.LnGet(ln, l, Evidence.LhBy0()) - Evidence.LnGet(ln, best, Evidence.LhBy0())) <= (h / 3)) {
                        emon.Port.CellsPush(tq, l);
                        Evidence.LnSet(ln, l, 15, TbHeld + k);
                        curx1 = Evidence.LnGet(ln, l, Evidence.LhX1());
                    }
                }
            }
            l += 1;
        }
        while ((more == 1) && (rounds < 6)) {
            more = 0;
            rounds += 1;
            pick = -1;
            l = l0;
            while (l < l1) {
                if (Evidence.LnGet(ln, l, 15) == 0) {
                    if ((Evidence.LnGet(ln, l, Evidence.LhY0()) >= (cury1 - 200)) && ((Evidence.LnGet(ln, l, Evidence.LhY0()) - cury1) <= ((h * 3) / 5))) {
                        if ((Evidence.LnGet(ln, l, Evidence.LhX0()) < tx1) && (Evidence.LnGet(ln, l, Evidence.LhX1()) > tx0)) {
                            if (!TbLineLabel(wd, et, ln, l)) {
                                if (Evidence.LnGet(ln, l, Evidence.LhY1()) < (ty0 + 300)) {
                                    if (pick < 0) {
                                        pick = l;
                                    }
                                }
                            }
                        }
                    }
                }
                l += 1;
            }
            if ((pick >= 0) && (above == 1)) {
                emon.Port.CellsPush(tq, pick);
                Evidence.LnSet(ln, pick, 15, TbHeld + k);
                cury1 = Evidence.LnGet(ln, pick, Evidence.LhY1());
                more = 1;
            }
        }
        emon.Port.CellsSet(tb, b + 15, emon.Port.CellsLen(tq) - emon.Port.CellsAt(tb, b + 14));
        return 1;
    }
    internal static int TbReject(emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx, int nt, int c0, int w0, int x0) {
        // Forget the candidate that was just built: every arena goes back to the length it had.
        emon.Port.CellsDrop(tb, nt * Tbs);
        emon.Port.CellsDrop(tc, c0 * Tcs);
        emon.Port.CellsDrop(tw, w0);
        emon.Port.CellsDrop(tx, x0);
        return 0;
    }
    internal static int TbTabularRows(emon.Port.Cells tb, int k, emon.Port.Cells tc) {
        // How many rows of table k have two cells or more with text.
        int b = k * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int row = -1;
        int cnt = 0;
        int total = 0;
        while (c < cend) {
            if (emon.Port.CellsAt(tc, c * Tcs) != row) {
                if (cnt >= 2) {
                    total += 1;
                }
                row = emon.Port.CellsAt(tc, c * Tcs);
                cnt = 0;
            }
            if (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0) {
                cnt += 1;
            }
            c += 1;
        }
        if (cnt >= 2) {
            total += 1;
        }
        return total;
    }
    internal static int TbLeadSingle(emon.Port.Cells tb, int k, emon.Port.Cells tc) {
        // P12.2: how many rows at the top of table k (at most two) have one cell with text: a spanning header (`December 31,` over the year columns, taken
        // in by `tb-head-reach`), a row that is no less a row of the table for not having two cells. `tb-score` leaves them out of the count of its rows.
        int b = k * Tbs;
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int row = 0;
        int cnt = 0;
        int lead = 0;
        int done = 0;
        while ((c < cend) && (done == 0)) {
            if (emon.Port.CellsAt(tc, c * Tcs) != row) {
                if (cnt == 1) {
                    lead += 1;
                } else {
                    done = 1;
                }
                row = emon.Port.CellsAt(tc, c * Tcs);
                cnt = 0;
            }
            if (emon.Port.CellsAt(tc, (c * Tcs) + 9) > 0) {
                cnt += 1;
            }
            c += 1;
        }
        if ((done == 0) && (cnt == 1)) {
            lead += 1;
        }
        return TbMin(lead, 2);
    }
    internal static int TbScore(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // The score (0 to 1000, 0 = not a table) of text-based candidate k of its profile (SPEC 10.5): prose in
        // columns is not a table, so cells that are long, or that end like sentences, refuse it. The whitespace
        // profile has no rules or fills to vouch for it and asks for more: three columns or a numeric column, and a header.
        int b = k * Tbs;
        int prof = emon.Port.CellsAt(tb, b + 5);
        int ncols = emon.Port.CellsAt(tb, b + 8);
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int ne = 0;
        int nw = 0;
        int nlong = 0;
        int nend = 0;
        int nprose = 0;
        int score = 0;
        while (c < cend) {
            int cn = emon.Port.CellsAt(tc, (c * Tcs) + 9);
            if (cn > 0) {
                ne += 1;
                nw += cn;
                if (cn > 8) {
                    nlong += 1;
                }
                if (cn >= 2) {
                    int fw = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8));
                    int lw2 = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + (cn - 1));
                    int c0 = emon.Port.CellsAt(et, Evidence.WdGet(wd, fw, Evidence.HdTstart()));
                    int ts2 = Evidence.WdGet(wd, lw2, Evidence.HdTstart());
                    int tl2 = Evidence.WdGet(wd, lw2, Evidence.HdTlen());
                    if ((c0 >= 97) && (c0 <= 122)) {
                        nprose += 1;
                    }
                    if ((tl2 > 1) && (emon.Port.CellsAt(et, ts2 + (tl2 - 1)) == 45)) {
                        nprose += 1;
                    }
                }
                if (cn >= 3) {
                    int lw = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (c * Tcs) + 8) + (cn - 1));
                    int ts = Evidence.WdGet(wd, lw, Evidence.HdTstart());
                    int tl = Evidence.WdGet(wd, lw, Evidence.HdTlen());
                    if ((tl > 0) && (emon.Port.CellsAt(et, ts + (tl - 1)) == 46)) {
                        nend += 1;
                    }
                }
            }
            c += 1;
        }
        if (ne < 4) {
            return 0;
        }
        if ((nprose * 10) > (ne * 3)) {
            return 0;
        }
        if ((prof == PfWhitespace) && ((ne * 100) < ((nrows * ncols) * 55))) {
            return 0;
        }
        if ((ne * 100) < ((nrows * ncols) * 35)) {
            return 0;
        }
        if ((nend * 5) > (ne * 2)) {
            return 0;
        }
        if ((nlong * 5) > ne) {
            return 0;
        }
        if (prof == PfWhitespace) {
            if ((nw * 10) > (ne * 40)) {
                return 0;
            }
            score = 400;
            if (ncols >= 3) {
                score += 100;
            }
            if (TbNumCols(tb, k, 1, wd, et, tc, tw) >= 1) {
                score += 100;
            }
            if (TbHeadRows(tb, k, wd, et, tc, tw) >= 1) {
                score += 100;
            }
            if (nrows >= 4) {
                score += 50;
            }
            if ((ncols == 2) && ((nrows >= 3) && ((TbNumCols(tb, k, 1, wd, et, tc, tw) == 1) && ((nw * 10) <= (ne * 25))))) {
                score += 100;
            }
            if (score < 600) {
                return 0;
            }
            return score;
        }
        if ((nw * 10) > (ne * 80)) {
            return 0;
        }
        if (prof == PfPartial) {
            return 800 + ((90 * TbTabularRows(tb, k, tc)) / TbMax(1, nrows - TbLeadSingle(tb, k, tc)));
        }
        return 750 + ((40 * TbTabularRows(tb, k, tc)) / TbMax(1, nrows));
    }
    internal static int TbBodyRow(emon.Port.Cells rw, int nr, int y0) {
        // The first row whose centre is below the top rule y0 (nr when none).
        int ra = 0;
        while ((ra < nr) && (((emon.Port.CellsAt(rw, (ra * Rws) + 6) + emon.Port.CellsAt(rw, (ra * Rws) + 7)) / 2) < y0)) {
            ra += 1;
        }
        return ra;
    }
    internal static int TbBackNear(emon.Port.Cells rw, int r, int below) {
        // 1 when row r, directly above row `below`, is a tabular row (two chunks or more) a pitch of at most 2.4 sizes of `below` above it:
        // the rule of the first versions for a header the top rule leaves out.
        if (emon.Port.CellsAt(rw, (r * Rws) + 9) < 2) {
            return 0;
        }
        if ((10 * (emon.Port.CellsAt(rw, (below * Rws) + 2) - emon.Port.CellsAt(rw, (r * Rws) + 2))) <= (24 * emon.Port.CellsAt(rw, (below * Rws) + 3))) {
            return 1;
        }
        return 0;
    }
    internal static int TbAligned(emon.Port.Cells rw, emon.Port.Cells sg, int r, int rb, int nr) {
        // 1 when the chunks of row r line up with the body's (D557): at least two of them, and three in five, have a left or a right edge
        // within `TB_HEAD_TOL` of an edge of a chunk of the body rows rb..nr (twelve of them at most; never row r itself, which D559's
        // `tb-gap-foreign` and `tb-tail-end` ask about among the rows around it).
        int nch = emon.Port.CellsAt(rw, (r * Rws) + 9);
        int sf = emon.Port.CellsAt(rw, (r * Rws) + 8);
        int bend = TbMin(nr, rb + 12);
        int s = 0;
        int hit = 0;
        int b = 0;
        int q = 0;
        int found = 0;
        while (s < nch) {
            found = 0;
            b = rb;
            while ((b < bend) && (found == 0)) {
                q = 0;
                while ((q < emon.Port.CellsAt(rw, (b * Rws) + 9)) && (found == 0)) {
                    int hs = sf + s;
                    int bs = emon.Port.CellsAt(rw, (b * Rws) + 8) + q;
                    if ((b != r) && (TbAbs(emon.Port.CellsAt(sg, (hs * Sgs) + 1) - emon.Port.CellsAt(sg, (bs * Sgs) + 1)) <= TbHeadTol)) {
                        found = 1;
                    }
                    if ((b != r) && (TbAbs(emon.Port.CellsAt(sg, (hs * Sgs) + 2) - emon.Port.CellsAt(sg, (bs * Sgs) + 2)) <= TbHeadTol)) {
                        found = 1;
                    }
                    q += 1;
                }
                b += 1;
            }
            hit += found;
            s += 1;
        }
        if (hit < 2) {
            return 0;
        }
        if ((hit * 5) >= (nch * 3)) {
            return 1;
        }
        return 0;
    }
    internal static int TbBackAligned(emon.Port.Cells rw, emon.Port.Cells sg, int r, int below, int rb, int nr) {
        // 1 when row r, directly above row `below`, is a tabular row at most `TB_HEAD_PITCH` tenths of a size of `below` above it whose
        // chunks line up with the body's columns (`tb-aligned`): a header in a smaller or another type, set further from the rule than
        // a line of text is (D557).
        if (emon.Port.CellsAt(rw, (r * Rws) + 9) < 2) {
            return 0;
        }
        if ((10 * (emon.Port.CellsAt(rw, (below * Rws) + 2) - emon.Port.CellsAt(rw, (r * Rws) + 2))) > (TbHeadPitch * emon.Port.CellsAt(rw, (below * Rws) + 3))) {
            return 0;
        }
        return TbAligned(rw, sg, r, rb, nr);
    }
    internal static int TbFirstRow(emon.Port.Cells rm, emon.Port.Cells rw, emon.Port.Cells sg, int nr, int y0, int align) {
        // The first row of a partial candidate: the first row whose centre is below the top rule y0, and the
        // tabular rows (at most three) directly above it, which are the header when the rule is the one under it: a row close above (at
        // most 2.4 sizes, `tb-back-near`) or, when `align` is 1 (y0 is the top rule of its whole chain: above it is nothing of the table's
        // own), one that lines up with the body's columns whatever its size and pitch (`tb-back-aligned`). P12.2: and then, when `align` is 1, the
        // one-chunk rows over a short rule (`tb-head-reach`: `December 31,` over the years).
        int rb = TbBodyRow(rw, nr, y0);
        int ra = rb;
        int n = 0;
        while ((ra > 0) && ((ra < nr) && ((n < 3) && ((TbBackNear(rw, ra - 1, ra) == 1) || ((align == 1) && (TbBackAligned(rw, sg, ra - 1, ra, rb, nr) == 1)))))) {
            ra -= 1;
            n += 1;
        }
        if ((align == 1) && (ra < nr)) {
            ra = TbHeadReach(rm, rw, sg, ra, nr - 1);
        }
        return ra;
    }
    internal static int TbFirstForced(emon.Port.Cells rw, int nr, int y0, int ra) {
        // 1 when a row of ra.. above the top rule y0 was taken for the header by alignment alone, not by being close (D557). P12.2: a row of one chunk
        // over a short rule (`tb-head-reach`) is no such row: the header rows are the bold ones, a spanning label and the years under it.
        int rb = TbBodyRow(rw, nr, y0);
        int r = ra;
        while (r < rb) {
            if ((TbBackNear(rw, r, r + 1) == 0) && (emon.Port.CellsAt(rw, (r * Rws) + 9) >= 2)) {
                return 1;
            }
            r += 1;
        }
        return 0;
    }
    internal static int TbExtend(emon.Port.Cells wd, int w0, int w1, emon.Port.Cells rw, emon.Port.Cells sg, int ra, int nr, int edge, int dir, emon.Port.Cells rm, emon.Port.Cells pr, emon.Port.Cells ry) {
        // D557: how far the rows ra..nr of a partial candidate go on the side `dir` (1 right, -1 left) of x `edge` (the candidate's edge there,
        // which the rules gave): over the words on the rows' own baselines that continue them. A column of cells the producer left unruled (the amounts
        // of a statement whose row borders stop at the description) is the table's. The words are followed while each starts within the table's own widest
        // gap (not under two sizes, not over twelve) of the reach so far: a wider one is a gutter. A vertical rule that spans three in five of the rows
        // stops them, and so does a horizontal one that goes on past the edge on the rows' height (another table's); at least three in five of the
        // rows must have such a word. Answers the new edge, or `edge`.
        int n = nr - ra;
        int size = emon.Port.CellsAt(rw, (ra * Rws) + 3);
        int nrl = TbRowsOf(rm, Rls);
        int e = dir * edge;
        int widest = 0;
        int gapmax = 0;
        int ytop = 2000000000;
        int ybot = -2000000000;
        int limit = 2000000000;
        int reach = e;
        int changed = 1;
        int r = 0;
        int s = 0;
        int w = 0;
        int i = 0;
        int hit = 0;
        int lo = 0;
        int hi = 0;
        int p = 0;
        int far = 0;
        int cx = 0;
        int cy = 0;
        int ov = 0;
        if (n < 3) {
            return edge;
        }
        r = ra;
        while (r < nr) {
            s = 0;
            while (s < (emon.Port.CellsAt(rw, (r * Rws) + 9) - 1)) {
                int a = emon.Port.CellsAt(rw, (r * Rws) + 8) + s;
                if ((emon.Port.CellsAt(sg, ((a + 1) * Sgs) + 1) - emon.Port.CellsAt(sg, (a * Sgs) + 2)) > widest) {
                    widest = emon.Port.CellsAt(sg, ((a + 1) * Sgs) + 1) - emon.Port.CellsAt(sg, (a * Sgs) + 2);
                }
                s += 1;
            }
            if (emon.Port.CellsAt(rw, (r * Rws) + 6) < ytop) {
                ytop = emon.Port.CellsAt(rw, (r * Rws) + 6);
            }
            if (emon.Port.CellsAt(rw, (r * Rws) + 7) > ybot) {
                ybot = emon.Port.CellsAt(rw, (r * Rws) + 7);
            }
            r += 1;
        }
        gapmax = widest;
        if (gapmax < (2 * size)) {
            gapmax = 2 * size;
        }
        if (gapmax > (12 * size)) {
            gapmax = 12 * size;
        }
        // What stops them: a vertical rule spanning the rows, another table's horizontal rule going on past the edge.
        i = 0;
        while (i < nrl) {
            p = emon.Port.CellsAt(rm, (i * Rls) + 1);
            lo = emon.Port.CellsAt(rm, (i * Rls) + 2);
            hi = emon.Port.CellsAt(rm, (i * Rls) + 3);
            if (emon.Port.CellsAt(rm, i * Rls) == 1) {
                ov = TbMin(hi, ybot) - TbMax(lo, ytop);
                if (((dir * p) > e) && ((ov * 5) >= ((ybot - ytop) * 3))) {
                    if ((dir * p) < limit) {
                        limit = dir * p;
                    }
                }
            } else if ((p >= ytop) && (p <= ybot)) {
                if (dir > 0) {
                    far = hi;
                } else {
                    far = lo;
                }
                if ((dir * far) > (e + PosTol)) {
                    return edge;
                }
            }
            i += 1;
        }
        // The words of the rows' baselines on that side, as (word, row) pairs in `pr`.
        emon.Port.CellsDrop(pr, 0);
        w = w0;
        while (w < w1) {
            if ((Evidence.WdGet(wd, w, Evidence.HdTlen()) > 0) && TbUpright(wd, w)) {
                cx = dir * ((Evidence.WdGet(wd, w, Evidence.HdX0()) + Evidence.WdGet(wd, w, Evidence.HdX1())) / 2);
                cy = (Evidence.WdGet(wd, w, Evidence.HdY0()) + Evidence.WdGet(wd, w, Evidence.HdY1())) / 2;
                if ((cx > e) && (cx < limit)) {
                    r = ra;
                    while (r < nr) {
                        if ((cy >= emon.Port.CellsAt(rw, (r * Rws) + 6)) && (cy <= emon.Port.CellsAt(rw, (r * Rws) + 7))) {
                            emon.Port.CellsPush(pr, w);
                            emon.Port.CellsPush(pr, r);
                            r = nr;
                        }
                        r += 1;
                    }
                }
            }
            w += 1;
        }
        while (changed == 1) {
            changed = 0;
            i = 0;
            while (i < (emon.Port.CellsLen(pr) / 2)) {
                w = emon.Port.CellsAt(pr, i * 2);
                if (dir > 0) {
                    lo = Evidence.WdGet(wd, w, Evidence.HdX0());
                    hi = Evidence.WdGet(wd, w, Evidence.HdX1());
                } else {
                    lo = 0 - Evidence.WdGet(wd, w, Evidence.HdX1());
                    hi = 0 - Evidence.WdGet(wd, w, Evidence.HdX0());
                }
                if ((lo <= (reach + gapmax)) && (hi > reach)) {
                    reach = hi;
                    changed = 1;
                }
                i += 1;
            }
        }
        if (reach <= e) {
            return edge;
        }
        // Rows that have a word inside the reach: three in five of them.
        emon.Port.CellsDrop(ry, 0);
        r = 0;
