    internal static int TbTailEnd(emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, int ex0, int ex1, int ytop, int ybot, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg) {
