            i += 1;
        }
        TbSortIdx(so, fl, 6, 1, 0);
        i = 0;
        while (i < n) {
            int f = emon.Port.CellsAt(so, i);
            int x0 = emon.Port.CellsAt(fl, f * 6);
            int y0 = emon.Port.CellsAt(fl, (f * 6) + 1);
            int x1 = emon.Port.CellsAt(fl, (f * 6) + 2);
            int y1 = emon.Port.CellsAt(fl, (f * 6) + 3);
