                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int TbBandHeader(emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, int sx0, int sx1, int y0, int gap, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg) {
