                            }
                        }
                    }
                }
                j = i;
                while (j <= last) {
                    if (emon.Port.CellsAt(used, j) == 2) {
                        emon.Port.CellsSet(used, j, 1);
                    }
                    j += 1;
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int TbTabularBaselineRows(emon.Port.Cells rw, int ra, int rb) {
        // How many of the baseline rows ra..rb are cut in two chunks or more.
        int r = ra;
        int n = 0;
        while (r < rb) {
            if (emon.Port.CellsAt(rw, (r * Rws) + 9) >= 2) {
                n += 1;
            }
            r += 1;
        }
        return n;
    }
    internal static int TbMedianPitch(emon.Port.Cells rw, int ra, int rb, emon.Port.Cells scratch) {
        // The median distance between the baselines of consecutive rows ra..rb (0 for fewer than two). `scratch` is clobbered.
        int r = ra + 1;
        emon.Port.CellsDrop(scratch, 0);
        while (r < rb) {
            emon.Port.CellsPush(scratch, emon.Port.CellsAt(rw, (r * Rws) + 2) - emon.Port.CellsAt(rw, ((r - 1) * Rws) + 2));
            r += 1;
        }
        if (emon.Port.CellsLen(scratch) < 2) {
            return 0;
        }
        TbSortNums(scratch);
        return emon.Port.CellsAt(scratch, emon.Port.CellsLen(scratch) / 2);
    }
    internal static int TbProseEdge(emon.Port.Cells tb, int k, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw) {
        // 1 when the first row of table k is a line of prose, 2 when the last is, 3 when both are: the line of a paragraph beside
        // or under a table that its row would have taken (D459). A line of prose is a row with one cell holding nine words or more, or
        // a row of which every cell has two words or more and begins with a lowercase letter (text set in chunks).
        int b = k * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
        int filled0 = 0;
        int words0 = 0;
        int low0 = 0;
        int filled1 = 0;
        int words1 = 0;
        int low1 = 0;
        int res = 0;
        while (c < cend) {
            int cb = c * Tcs;
            int cn = emon.Port.CellsAt(tc, cb + 9);
            if (cn > 0) {
                int fw = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, cb + 8));
                int c0 = emon.Port.CellsAt(et, Evidence.WdGet(wd, fw, Evidence.HdTstart()));
                int low = 0;
                if ((cn >= 2) && ((c0 >= 97) && (c0 <= 122))) {
                    low = 1;
                }
                if (emon.Port.CellsAt(tc, cb) == 0) {
                    filled0 += 1;
                    low0 += low;
                    if (cn > words0) {
                        words0 = cn;
                    }
                }
                if (emon.Port.CellsAt(tc, cb) == (nrows - 1)) {
                    filled1 += 1;
                    low1 += low;
                    if (cn > words1) {
                        words1 = cn;
                    }
                }
            }
            c += 1;
        }
        if (nrows < 4) {
            return 0;
        }
        if (((filled0 == 1) && (words0 >= 9)) || ((filled0 >= 2) && (low0 == filled0))) {
            res = 1;
        }
        if (((filled1 == 1) && (words1 >= 9)) || ((filled1 >= 2) && (low1 == filled1))) {
            res += 2;
        }
        return res;
    }
    internal static int TbHeadReach(emon.Port.Cells rm, emon.Port.Cells rw, emon.Port.Cells sg, int a, int b) {
        // P12.2 (smoke review, issue 3: a statement's `December 31,` over its years): the first row of a run whose rows are a..b, taking in the one-chunk rows
        // above it that are headers: a row of one chunk at most 2.4 sizes over the next, with a rule drawn under it between the two that lies under the text (the
        // rule is as wide as the text, and shorter than nine in ten of the run: a rule as wide as the table is its top border, and what is over it a title). At
        // most two rows. Answers the first row.
        int nrl = TbRowsOf(rm, Rls);
        int minx = 2000000000;
        int maxx = -2000000000;
        int r = a;
        int n = 0;
        int i = 0;
        int more = 1;
        int found = 0;
        i = a;
        while (i <= b) {
            if (emon.Port.CellsAt(rw, (i * Rws) + 4) < minx) {
                minx = emon.Port.CellsAt(rw, (i * Rws) + 4);
            }
            if (emon.Port.CellsAt(rw, (i * Rws) + 5) > maxx) {
                maxx = emon.Port.CellsAt(rw, (i * Rws) + 5);
            }
            i += 1;
        }
        while ((more == 1) && ((r > 0) && (n < 2))) {
            more = 0;
            int p = r - 1;
            if (emon.Port.CellsAt(rw, (p * Rws) + 9) == 1) {
                if ((10 * (emon.Port.CellsAt(rw, (r * Rws) + 2) - emon.Port.CellsAt(rw, (p * Rws) + 2))) <= (24 * emon.Port.CellsAt(rw, (r * Rws) + 3))) {
                    int tx0 = emon.Port.CellsAt(sg, (emon.Port.CellsAt(rw, (p * Rws) + 8) * Sgs) + 1);
                    int tx1 = emon.Port.CellsAt(sg, (emon.Port.CellsAt(rw, (p * Rws) + 8) * Sgs) + 2);
                    int ylo = emon.Port.CellsAt(rw, (p * Rws) + 7);
                    int yhi = emon.Port.CellsAt(rw, (r * Rws) + 6);
                    found = 0;
                    i = 0;
                    while (i < nrl) {
                        if (emon.Port.CellsAt(rm, i * Rls) == 0) {
                            int pos = emon.Port.CellsAt(rm, (i * Rls) + 1);
                            int a0 = emon.Port.CellsAt(rm, (i * Rls) + 2);
                            int a1 = emon.Port.CellsAt(rm, (i * Rls) + 3);
                            if ((pos >= (ylo - 300)) && (pos <= (yhi + 300))) {
                                if ((a0 <= (tx0 + 300)) && (a1 >= (tx1 - 300))) {
                                    if ((10 * (a1 - a0)) < (9 * (maxx - minx))) {
                                        found = 1;
                                    }
                                }
                            }
                        }
                        i += 1;
                    }
                    if (found == 1) {
                        r = p;
                        n += 1;
                        more = 1;
                    }
                }
            }
        }
        return r;
    }
    internal static int TbWhitespaceRun(int page, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells rm, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx, int ra, int rb) {
        // The rows ra..rb (inclusive) as a whitespace candidate: its rows of one chunk at either end are not in it, and a
        // run that is refused as a whole is tried again without its last row (the lines that follow a table, set in two
        // chunks like a label and its text, join the run once the rows are right; D459). Three rows cut in two chunks at least.
        int a = ra;
        int jj = rb;
        int again = 0;
        while ((a < jj) && (emon.Port.CellsAt(rw, (a * Rws) + 9) < 2)) {
            a += 1;
        }
        jj = TbTrimEnd(rw, sg, a, jj);
        if (TbTabularBaselineRows(rw, a, jj + 1) >= 3) {
            again = 1;
        }
        while (again == 1) {
            again = 0;
            int nt = TbRowsOf(tb, Tbs);
            int c0 = TbRowsOf(tc, Tcs);
            int wl0 = emon.Port.CellsLen(tw);
            int xl0 = emon.Port.CellsLen(tx);
            int h = TbHeadReach(rm, rw, sg, a, jj);
            int t = TbTextGrid(wd, et, wl, rw, sg, rm, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, h, jj + 1, PfWhitespace, 0, 0, 2000000000, 2000000000, -2000000000, -2000000000);
            if (t >= 0) {
                int sc = TbScore(tb, t, wd, et, tc, tw);
                int pe = TbProseEdge(tb, t, wd, et, tc, tw);
                if ((sc == 0) || (pe > 0)) {
                    TbReject(tb, tc, tw, tx, nt, c0, wl0, xl0);
                    if ((sc == 0) || (pe >= 2)) {
                        jj -= 1;
                    }
                    if ((pe == 1) || (pe == 3)) {
                        a += 1;
                    }
                    jj = TbTrimEnd(rw, sg, a, jj);
                    while ((a < jj) && (emon.Port.CellsAt(rw, (a * Rws) + 9) < 2)) {
                        a += 1;
                    }
                    // ...until three rows are left, and no more rows are let go than are kept (a run of columns of text
                    // that is refused is not a table with some prose after it)
                    if ((TbTabularBaselineRows(rw, a, jj + 1) >= 3) && (((rb - jj) + (a - ra)) <= ((jj - a) + 1))) {
                        again = 1;
                    }
                } else {
                    emon.Port.CellsSet(tb, (t * Tbs) + 6, sc);
                }
            }
        }
        return 0;
    }
    internal static bool TbUnder(emon.Port.Cells rw, emon.Port.Cells sg, int j, int r) {
        // P12.2: does the one chunk of row r stand under a chunk of row j: its left or its right edge within `TB_HEAD_TOL` of one of that row's chunks' edges
        // (the lines of a cell that wraps keep to its column; a title centred under a table does not).
        int x0 = emon.Port.CellsAt(sg, (emon.Port.CellsAt(rw, (r * Rws) + 8) * Sgs) + 1);
        int x1 = emon.Port.CellsAt(sg, (emon.Port.CellsAt(rw, (r * Rws) + 8) * Sgs) + 2);
        int q = 0;
        while (q < emon.Port.CellsAt(rw, (j * Rws) + 9)) {
            int s = emon.Port.CellsAt(rw, (j * Rws) + 8) + q;
            if ((TbAbs(x0 - emon.Port.CellsAt(sg, (s * Sgs) + 1)) <= TbHeadTol) || (TbAbs(x1 - emon.Port.CellsAt(sg, (s * Sgs) + 2)) <= TbHeadTol)) {
                return 1 == 1;
            }
            q += 1;
        }
        return 0 == 1;
    }
    internal static int TbTrimEnd(emon.Port.Cells rw, emon.Port.Cells sg, int a, int jj) {
        // P12.2: the last row of the rows a..jj of a whitespace run, the rows of one chunk at its end let go: but not the continuation lines of the last row of
        // two chunks or more, when there are up to six and each is tight under the one before and under a chunk of that row (a cell that wraps in the last
        // row: the Agami statements).
        int t = jj;
        int tight = 1;
        while ((t > a) && (emon.Port.CellsAt(rw, (t * Rws) + 9) < 2)) {
            if ((20 * (emon.Port.CellsAt(rw, (t * Rws) + 2) - emon.Port.CellsAt(rw, ((t - 1) * Rws) + 2))) > (27 * emon.Port.CellsAt(rw, (t * Rws) + 3))) {
                tight = 0;
            }
            t -= 1;
        }
        if ((tight == 1) && ((jj - t) <= 6)) {
            int r = t + 1;
            while (r <= jj) {
                if (!TbUnder(rw, sg, t, r)) {
                    return t;
                }
                r += 1;
            }
            t = jj;
        }
        return t;
    }
    internal static int TbRunTail(emon.Port.Cells rw, emon.Port.Cells sg, int nr, int k) {
        // P12.2 (smoke review, issue 6): the rows of one chunk from row k on that a whitespace run takes in, answered as the row of two chunks or more that
        // follows them, -1 when the run ends before them. They are the continuation lines of a cell that wraps when each is tight under the row before
        // it (at most 1.35 sizes: up to six of them) and stands under a chunk of the row k - 1 (`tb-under`), the label of a section and its sub-label when they
        // are not (up to two); and no row is more than three sizes from the one before it.
        // When no row of two chunks follows them (the page ends, or a gap does) they are the run's last rows when they are the continuation lines.
        int m = k;
        int tight = 1;
        int stop = 0;
        while ((m < nr) && ((stop == 0) && (emon.Port.CellsAt(rw, (m * Rws) + 9) == 1))) {
            int pitch = emon.Port.CellsAt(rw, (m * Rws) + 2) - emon.Port.CellsAt(rw, ((m - 1) * Rws) + 2);
            int size = emon.Port.CellsAt(rw, (m * Rws) + 3);
            if ((pitch * 10) > (size * 30)) {
                stop = 1;
            } else {
                if (((pitch * 20) > (size * 27)) || !TbUnder(rw, sg, k - 1, m)) {
                    tight = 0;
                }
                m += 1;
            }
        }
        if ((stop == 0) && (m < nr)) {
            if ((tight == 1) && ((m - k) <= 6)) {
                return m;
            }
            // A label is short (six words at most): a paragraph between two tables is no label of either.
            if (((m - k) <= 2) && ((emon.Port.CellsAt(rw, (k * Rws) + 1) <= 6) && (((m - k) == 1) || (emon.Port.CellsAt(rw, ((k + 1) * Rws) + 1) <= 6)))) {
                return m;
            }
            return -1;
        }
        if ((tight == 1) && ((m > k) && ((m - k) <= 6))) {
            return m;
        }
        return -1;
    }
    internal static int TbWhitespacePage(int page, emon.Port.Cells wd, emon.Port.Cells et, int w0, int w1, emon.Port.Cells rm, emon.Port.Cells wl, emon.Port.Cells rw, emon.Port.Cells sg, emon.Port.Cells ch, emon.Port.Cells st, emon.Port.Cells en, emon.Port.Cells rmap, emon.Port.Cells gm, emon.Port.Cells gs, emon.Port.Cells ry, emon.Port.Cells pr, emon.Port.Cells so, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tx) {
        // The rows of the whole page, in runs of rows that are cut in two or more chunks (a row of one chunk
        // goes in a run when a row of two follows it, and so do two, P12.2: a section's label and its sub-label, `ASSETS` and `Insurance and Other:`),
        // each run of three such rows or more a whitespace candidate.
        int nr = TbRows(wd, et, w0, w1, -2000000000, -2000000000, 2000000000, 2000000000, wl, rw, sg);
        int i = 0;
        int j = 0;
        int k = 0;
        int ntab = 0;
        int more = 1;
        while (i < nr) {
            if (emon.Port.CellsAt(rw, (i * Rws) + 9) >= 2) {
                j = i;
                ntab = 1;
                more = 1;
                while (more == 1) {
                    k = j + 1;
                    if (k >= nr) {
                        more = 0;
                    } else {
                        int gapk = emon.Port.CellsAt(rw, (k * Rws) + 2) - emon.Port.CellsAt(rw, (j * Rws) + 2);
                        int szk = emon.Port.CellsAt(rw, (k * Rws) + 3);
                        if ((gapk * 10) > (szk * 30)) {
                            more = 0;
                        } else if (emon.Port.CellsAt(rw, (k * Rws) + 9) >= 2) {
                            j = k;
                            ntab += 1;
                        } else {
                            int m = TbRunTail(rw, sg, nr, k);
                            if (m < 0) {
                                more = 0;
                            } else {
                                j = m - 1;
                            }
                        }
                    }
                }
                j = TbTrimEnd(rw, sg, i, j);
                if (ntab >= 3) {
                    int a = i;
                    int e = j;
                    int med = TbMedianPitch(rw, i, j + 1, st);
                    // A row set apart from the run's body by more than twice the run's median pitch is not in it: a page's running
                    // header above a table, a label below it. The rows were once cut in halves by a tilted scan and these stood alone;
                    // set right, they join the run (D459).
                    if (med > 0) {
                        while ((a < e) && ((10 * (emon.Port.CellsAt(rw, ((a + 1) * Rws) + 2) - emon.Port.CellsAt(rw, (a * Rws) + 2))) > (20 * med))) {
                            a += 1;
                        }
                        while ((e > a) && ((10 * (emon.Port.CellsAt(rw, (e * Rws) + 2) - emon.Port.CellsAt(rw, ((e - 1) * Rws) + 2))) > (20 * med))) {
                            e -= 1;
                        }
                    }
                    TbWhitespaceRun(page, wd, et, rm, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, a, e);
                }
            } else {
                j = i;
            }
            i = j + 1;
        }
        return 0;
    }
    internal static bool TbLineRepeated(emon.Port.Cells ln, emon.Port.Cells wd, emon.Port.Cells et, int l, int other) {
        // P12.2: is line l on page `other` too: a line there with the same words (the first and the last, and as many) at the same place, within 3 pt:
        // a running header (a bank's name and address over every page) that the furniture stage will take out, and no body of the page.
        int n = Evidence.LnCount(ln);
        int lc = Evidence.LnGet(ln, l, Evidence.LhCount());
        int lf = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int m = 0;
        while (m < n) {
            if ((Evidence.LnGet(ln, m, Evidence.LhPage()) == other) && (Evidence.LnGet(ln, m, Evidence.LhCount()) == lc)) {
                if ((TbAbs(Evidence.LnGet(ln, m, Evidence.LhY0()) - Evidence.LnGet(ln, l, Evidence.LhY0())) <= 300) && (TbAbs(Evidence.LnGet(ln, m, Evidence.LhX0()) - Evidence.LnGet(ln, l, Evidence.LhX0())) <= 300)) {
                    if (TbWordSame(wd, et, lf, Evidence.LnGet(ln, m, Evidence.LhFirst())) && TbWordSame(wd, et, lf + (lc - 1), Evidence.LnGet(ln, m, Evidence.LhFirst()) + (lc - 1))) {
                        return 1 == 1;
                    }
                }
            }
            m += 1;
        }
        return 0 == 1;
    }
    internal static bool TbBodyLineOutside(emon.Port.Cells ln, emon.Port.Cells wd, emon.Port.Cells et, int page, int y0, int y1, int zlo, int zhi, int other) {
        // Is there a line, not claimed by a table, on `page` whose centre is in y0..y1 and outside the furniture
        // zones (above zlo, below zhi), and is not one that page `other` has too (`tb-line-repeated`; 0 for none)?
        int n = Evidence.LnCount(ln);
        int l = 0;
        while (l < n) {
            if ((Evidence.LnGet(ln, l, Evidence.LhPage()) == page) && (Evidence.LnGet(ln, l, 15) == 0)) {
                int cy = (Evidence.LnGet(ln, l, Evidence.LhY0()) + Evidence.LnGet(ln, l, Evidence.LhY1())) / 2;
                if ((cy >= y0) && ((cy <= y1) && ((cy > zlo) && (cy < zhi)))) {
                    if ((other == 0) || !TbLineRepeated(ln, wd, et, l, other)) {
                        return 1 == 1;
                    }
                }
            }
            l += 1;
        }
        return 0 == 1;
    }
    internal static bool TbSameColumns(emon.Port.Cells tb, int a, int b, emon.Port.Cells tx) {
        // The same number of columns, every boundary of b within 1/60 of the width of a's (at least 5 pt) of a's.
        int na = emon.Port.CellsAt(tb, (a * Tbs) + 17);
        int nb = emon.Port.CellsAt(tb, (b * Tbs) + 17);
        int xa = emon.Port.CellsAt(tb, (a * Tbs) + 16);
        int xb = emon.Port.CellsAt(tb, (b * Tbs) + 16);
        int i = 0;
        if (na != nb) {
            return 0 == 1;
        }
        if (na < 3) {
            return 0 == 1;
        }
        int tol = TbMax(1000, (emon.Port.CellsAt(tx, xa + (na - 1)) - emon.Port.CellsAt(tx, xa)) / 20);
        while (i < na) {
            if (TbAbs(emon.Port.CellsAt(tx, xa + i) - emon.Port.CellsAt(tx, xb + i)) > tol) {
                return 0 == 1;
            }
            i += 1;
        }
        return 1 == 1;
    }
    internal static bool TbWordSame(emon.Port.Cells wd, emon.Port.Cells et, int a, int b) {
        int n = Evidence.WdGet(wd, a, Evidence.HdTlen());
        int sa = Evidence.WdGet(wd, a, Evidence.HdTstart());
        int sb = Evidence.WdGet(wd, b, Evidence.HdTstart());
        int i = 0;
        if (n != Evidence.WdGet(wd, b, Evidence.HdTlen())) {
            return 0 == 1;
        }
        while (i < n) {
            if (emon.Port.CellsAt(et, sa + i) != emon.Port.CellsAt(et, sb + i)) {
                return 0 == 1;
            }
            i += 1;
        }
        return 1 == 1;
    }
    internal static bool TbRowSame(emon.Port.Cells tb, int a, int ra, int b, int rb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells wd, emon.Port.Cells et) {
        // Does row ra of table a say, cell for cell and word for word, what row rb of table b says.
        int ca0 = emon.Port.CellsAt(tb, (a * Tbs) + 9);
        int ca1 = ca0 + emon.Port.CellsAt(tb, (a * Tbs) + 10);
        int cb0 = emon.Port.CellsAt(tb, (b * Tbs) + 9);
        int cb1 = cb0 + emon.Port.CellsAt(tb, (b * Tbs) + 10);
        int i = ca0;
        int j = cb0;
        int k = 0;
        while ((i < ca1) && (emon.Port.CellsAt(tc, i * Tcs) != ra)) {
            i += 1;
        }
        while ((j < cb1) && (emon.Port.CellsAt(tc, j * Tcs) != rb)) {
            j += 1;
        }
        while ((i < ca1) && ((j < cb1) && ((emon.Port.CellsAt(tc, i * Tcs) == ra) && (emon.Port.CellsAt(tc, j * Tcs) == rb)))) {
            if ((emon.Port.CellsAt(tc, (i * Tcs) + 1) != emon.Port.CellsAt(tc, (j * Tcs) + 1)) || (emon.Port.CellsAt(tc, (i * Tcs) + 9) != emon.Port.CellsAt(tc, (j * Tcs) + 9))) {
                return 0 == 1;
            }
            k = 0;
            while (k < emon.Port.CellsAt(tc, (i * Tcs) + 9)) {
                if (!TbWordSame(wd, et, emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (i * Tcs) + 8) + k), emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (j * Tcs) + 8) + k))) {
                    return 0 == 1;
                }
                k += 1;
            }
            i += 1;
            j += 1;
        }
        return ((i >= ca1) || (emon.Port.CellsAt(tc, i * Tcs) != ra)) && ((j >= cb1) || (emon.Port.CellsAt(tc, j * Tcs) != rb));
    }
    internal static bool TbCaptionAgain(emon.Port.Cells tb, int a, int b, emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells tq) {
        // Does table b have a caption, and is it the label (keyword and number) of table a's?
        int qa = emon.Port.CellsAt(tb, (a * Tbs) + 15);
        if (qa == 0) {
            return 0 == 1;
        }
        int wa = Evidence.LnGet(ln, emon.Port.CellsAt(tq, emon.Port.CellsAt(tb, (a * Tbs) + 14)), Evidence.LhFirst());
        int wb = Evidence.LnGet(ln, emon.Port.CellsAt(tq, emon.Port.CellsAt(tb, (b * Tbs) + 14)), Evidence.LhFirst());
        return TbWordSame(wd, et, wa, wb) && TbWordSame(wd, et, wa + 1, wb + 1);
    }
    internal static int TbUnfoot(emon.Port.Cells tb, int a, emon.Port.Cells tc) {
        // A table that goes on has no foot on this page: its bold last row is a row.
        int b = a * Tbs;
        int nrows = emon.Port.CellsAt(tb, b + 7);
        int nfoot = emon.Port.CellsAt(tb, b + 12);
        int cfirst = emon.Port.CellsAt(tb, b + 9);
        int cend = cfirst + emon.Port.CellsAt(tb, b + 10);
        int c = cfirst;
